function getSupabase(reqPath) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'GET',
      headers: { 'apikey': SERVICE_KEY, 'Authorization': 'Bearer ' + SERVICE_KEY }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

function normalizar(txt) {
  return (txt || '').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

function matchDoc(docNombre, searchDoc) {
  if (!searchDoc) return true;
  const nDoc = normalizar(docNombre).replace(/\b(dr|dra|doctor|doctora)\b\.?/g, '').trim();
  const nSearch = normalizar(searchDoc).replace(/\b(dr|dra|doctor|doctora)\b\.?/g, '').trim();
  const words = nSearch.split(/\s+/).filter(w => w.length >= 3);
  if (words.length === 0) return true;
  return words.some(w => nDoc.includes(w));
}

function matchEsp(docEsp, searchEsp) {
  if (!searchEsp) return true;
  const nDoc = normalizar(docEsp);
  const nSearch = normalizar(searchEsp);
  const words = nSearch.split(/\s+/).filter(w => w.length >= 3);
  if (words.length === 0) return true;
  return words.some(w => nDoc.includes(w)) || nDoc.includes(nSearch) || nSearch.includes(nDoc);
}

function filtrarDoctores(lista, docSolicitado, espSolicitada) {
  let res = lista;
  if (docSolicitado) {
    const porDoc = res.filter(d => matchDoc(d.nombre, docSolicitado));
    if (porDoc.length > 0) {
      if (espSolicitada) {
        const porDocYEsp = porDoc.filter(d => matchEsp(d.especialidad, espSolicitada));
        res = porDocYEsp.length > 0 ? porDocYEsp : porDoc;
      } else {
        res = porDoc;
      }
    } else if (espSolicitada) {
      res = res.filter(d => matchEsp(d.especialidad, espSolicitada));
    }
  } else if (espSolicitada) {
    res = res.filter(d => matchEsp(d.especialidad, espSolicitada));
  }
  return res;
}

const diasSemana = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];

function formatFechaEsp(d) {
  return diasSemana[d.getDay()] + ' ' + d.getDate() + ' de ' + meses[d.getMonth()] + ' de ' + d.getFullYear();
}

function toIsoDate(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return y + '-' + m + '-' + day;
}

function siguienteDiaHabil(fromDate) {
  let d = new Date(fromDate);
  do {
    d.setDate(d.getDate() + 1);
  } while (d.getDay() === 0 || d.getDay() === 6);
  d.setHours(0, 0, 0, 0);
  return d;
}

function atiendeElDia(diasAtencionStr, dw) {
  if (!diasAtencionStr) return true;
  const s = normalizar(diasAtencionStr);
  if (s.includes('todos') || s.includes('lunes a viernes') || s.includes('lun a vie')) return dw >= 1 && dw <= 5;
  if (s.includes('lunes a jueves') || s.includes('lun a jue')) return dw >= 1 && dw <= 4;
  if (s.includes('martes a viernes') || s.includes('mar a vie')) return dw >= 2 && dw <= 5;
  const checks = { 1: ['lun'], 2: ['mar'], 3: ['mie'], 4: ['jue'], 5: ['vie'] };
  const tokens = checks[dw] || [];
  return tokens.some(t => s.includes(t));
}

try {
  const doctoresBD = await getSupabase('/rest/v1/clinica_doctores?activo=eq.true&select=*');
  const listaDoctores = Array.isArray(doctoresBD) ? doctoresBD : [];

  // Fecha y hora actual en zona horaria local de atención (Argentina / Buenos Aires)
  const now = new Date(new Date().toLocaleString("en-US", { timeZone: "America/Argentina/Buenos_Aires" }));
  const todayIso = toIsoDate(now);
  const currentHour = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');

  // La clínica cierra a las 20:30 hs y el último turno inicia a las 19:00 hs
  const clinicaCerradaHoy = (currentHour >= '19:00') || (now.getDay() === 0 || now.getDay() === 6);

  let targetDate = null;
  let fechaStr = input.fecha || '';
  let avisoCierre = '';

  if (!fechaStr) {
    const m = rawStr.match(/202[0-9]-[0-1][0-9]-[0-3][0-9]/);
    if (m) fechaStr = m[0];
  }

  if (fechaStr) {
    const parts = fechaStr.split('-');
    if (parts.length === 3) {
      let y = parseInt(parts[0]);
      if (y < now.getFullYear()) y = now.getFullYear();
      targetDate = new Date(y, parseInt(parts[1]) - 1, parseInt(parts[2]));
      targetDate.setHours(0, 0, 0, 0);
      fechaStr = toIsoDate(targetDate);
    }
  }

  // Detección de expresiones temporales
  if (!targetDate) {
    if (rawStr.includes('mañana') || rawStr.includes('manana')) {
      targetDate = siguienteDiaHabil(now);
      fechaStr = toIsoDate(targetDate);
    } else if (rawStr.includes('hoy')) {
      if (clinicaCerradaHoy) {
        targetDate = siguienteDiaHabil(now);
        fechaStr = toIsoDate(targetDate);
        avisoCierre = `La clínica se encuentra CERRADA en este momento (horario de atención: 08:30 a 20:30 hs; hora actual: ${currentHour} hs). Ya no es posible agendar turnos para hoy. Te ofrecemos disponibilidad a partir de mañana (${formatFechaEsp(targetDate)}):`;
      } else {
        targetDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        targetDate.setHours(0, 0, 0, 0);
        fechaStr = toIsoDate(targetDate);
      }
    } else {
      const mapaDias = { 'lunes': 1, 'martes': 2, 'miercoles': 3, 'miércoles': 3, 'jueves': 4, 'viernes': 5 };
      for (const [nom, diaNum] of Object.entries(mapaDias)) {
        if (rawStr.includes(nom)) {
          let d = new Date(now);
          do { d.setDate(d.getDate() + 1); } while (d.getDay() !== diaNum);
          d.setHours(0, 0, 0, 0);
          targetDate = d;
          fechaStr = toIsoDate(d);
          break;
        }
      }
    }
  }

  // Si aún no hay fecha:
  if (!targetDate) {
    if (clinicaCerradaHoy) {
      targetDate = siguienteDiaHabil(now);
      fechaStr = toIsoDate(targetDate);
      avisoCierre = `La clínica ha finalizado su horario de atención por hoy (08:30 a 20:30 hs; son las ${currentHour} hs). Te ofrecemos los primeros turnos disponibles para mañana (${formatFechaEsp(targetDate)}):`;
    } else {
      targetDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      targetDate.setHours(0, 0, 0, 0);
      fechaStr = toIsoDate(targetDate);
    }
  }

  const cuadroMedico = listaDoctores.map(d => ({
    id: d.id,
    nombre: d.nombre_completo,
    especialidad: d.especialidad,
    dias_atencion: d.dias_atencion || 'Lunes a Viernes',
    horario_inicio: (d.horario_inicio ? d.horario_inicio.slice(0, 5) : '09:00'),
    horario_fin: (d.horario_fin ? d.horario_fin.slice(0, 5) : '20:00'),
    consultorio: d.consultorio_asignado
  }));

  const hoyCero = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  if (targetDate < hoyCero) {
    return JSON.stringify({ disponible: false, error: 'FECHA_PASADA', motivo: 'La fecha solicitada ya pasó. Por favor elige una fecha futura.' });
  }

  const dw = targetDate.getDay();
  if (dw === 0 || dw === 6) {
    const sig = siguienteDiaHabil(targetDate);
    return JSON.stringify({
      disponible: false,
      error: 'FIN_DE_SEMANA',
      motivo: `La clínica abre de lunes a viernes. El ${formatFechaEsp(targetDate)} es fin de semana. Te ofrecemos turnos para el ${formatFechaEsp(sig)}.`
    });
  }

  // 1. Obtener citas agendadas en tiempo real para ese día en Supabase
  const citasDia = await getSupabase(`/rest/v1/clinica_citas?fecha_hora_inicio=gte.${fechaStr}T00:00:00Z&fecha_hora_inicio=lte.${fechaStr}T23:59:59Z&estado=neq.CANCELADA&select=*`);
  const listaCitas = Array.isArray(citasDia) ? citasDia : [];

  const ocupadosPorDoctor = {};
  for (const c of listaCitas) {
    if (!c.fecha_hora_inicio) continue;
    const cDate = new Date(c.fecha_hora_inicio);
    const horaIso = String(cDate.getUTCHours()).padStart(2, '0') + ':' + String(cDate.getUTCMinutes()).padStart(2, '0');
    if (!ocupadosPorDoctor[c.doctor_id]) ocupadosPorDoctor[c.doctor_id] = [];
    ocupadosPorDoctor[c.doctor_id].push(horaIso);
  }

  const baseSlots = ['09:30', '10:30', '11:30', '12:30', '16:00', '17:00', '18:00', '19:00'];
  const esMismoDiaHoy = (fechaStr === todayIso);

  const doctoresDelDia = cuadroMedico.filter(doc => atiendeElDia(doc.dias_atencion, dw));

  const doctoresConTurnos = doctoresDelDia.map(doc => {
    let docSlots = baseSlots.filter(s => s >= doc.horario_inicio && s < doc.horario_fin);

    // FILTRO ESTRICTO: Si la consulta es para HOY, descartar turnos pasados respecto a la hora actual
    if (esMismoDiaHoy) {
      docSlots = docSlots.filter(s => s > currentHour);
    }

    const ocupados = ocupadosPorDoctor[doc.id] || [];
    const libres = docSlots.filter(s => !ocupados.includes(s));

    return {
      id: doc.id,
      nombre: doc.nombre,
      especialidad: doc.especialidad,
      horario: `${doc.horario_inicio} a ${doc.horario_fin}`,
      turnos_libres: libres,
      turnos_ocupados: ocupados
    };
  });

  const docSolicitado = (input.doctor || '').toString().trim();
  const espSolicitada = (input.especialidad || '').toString().trim();

  // Si era hoy y no queda ningún turno libre porque ya pasaron todos los horarios:
  const totalLibresHoy = doctoresConTurnos.reduce((acc, d) => acc + d.turnos_libres.length, 0);
  if (esMismoDiaHoy && totalLibresHoy === 0) {
    const manana = siguienteDiaHabil(now);
    const mananaIso = toIsoDate(manana);
    const dwManana = manana.getDay();

    const citasManana = await getSupabase(`/rest/v1/clinica_citas?fecha_hora_inicio=gte.${mananaIso}T00:00:00Z&fecha_hora_inicio=lte.${mananaIso}T23:59:59Z&estado=neq.CANCELADA&select=*`);
    const listaCitasM = Array.isArray(citasManana) ? citasManana : [];
    const ocupadosM = {};
    for (const c of listaCitasM) {
      if (!c.fecha_hora_inicio) continue;
      const cDate = new Date(c.fecha_hora_inicio);
