      timeZone: 'America/Argentina/Buenos_Aires',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });

    const mensaje = `⚠️ <b>FALLO EN AUTOMATIZACIÓN - ATENCIÓN MANUAL REQUERIDA</b> ⚠️\n\n` +
      `📌 <b>Proceso:</b> ${proceso} (${accion})\n` +
      `👤 <b>Paciente:</b> ${paciente || 'No especificado'} (DNI: ${dni || 'S/D'})\n` +
      `📅 <b>Turno:</b> ${fecha || 'S/F'} a las ${hora || 'S/H'} hs\n` +
      `❌ <b>Detalle del Fallo:</b> ${error}\n` +
      `⏰ <b>Hora del Incidente:</b> ${horaActual} hs\n\n` +
      `👉 <i>Recepcionistas: Por favor realizar la acción manualmente en la web del ERP para asegurar la consistencia.</i>`;

    const postData = JSON.stringify({
      chat_id: CANAL_RECEPCION,
      text: mensaje,
      parse_mode: 'HTML'
    });

    const req = https.request({
      hostname: 'api.telegram.org',
      port: 443,
      path: '/bot' + BOT_TOKEN + '/sendMessage',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    }, res => resolve({ ok: res.statusCode === 200 }));
    req.on('error', () => resolve({ ok: false }));
    req.write(postData);
    req.end();
  });
}

function getSupabase(reqPath) {
  return new Promise((resolve, reject) => {
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'GET',
      headers: { 'apikey': SERVICE_KEY, 'Authorization': 'Bearer ' + SERVICE_KEY }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.end();
  });
}

function patchSupabase(reqPath, body) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(body);
    const req = https.request({
      hostname: HOST,
      port: 443,
      path: reqPath,
      method: 'PATCH',
      headers: {
        'apikey': SERVICE_KEY,
        'Authorization': 'Bearer ' + SERVICE_KEY,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation'
      }
    }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try { resolve(JSON.parse(data)); } catch (e) { resolve(data); }
      });
    });
    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

function dispararUiPath(params) {
  return new Promise((resolve) => {
    const postData = 'grant_type=client_credentials&client_id=55df9cd9-2386-4443-96aa-4387bed2a839&client_secret=' + encodeURIComponent('RXn7yg~(ebwkWU%D8hcxa?nc8U8Oel*xoWXM_phG2JquDmV1t(g_JEOp#mNXEf?j') + '&scope=OR.Jobs%20OR.Execution';
