            method: 'POST',
            headers: {
              'Authorization': 'Bearer ' + parsedToken.access_token,
              'X-UIPATH-OrganizationUnitId': '7745816',
              'Content-Type': 'application/json',
              'Content-Length': Buffer.byteLength(jobPayload)
            }
          }, resJob => {
            let jData = '';
            resJob.on('data', c => jData += c);
            resJob.on('end', () => {
              resolve({ ok: resJob.statusCode === 201, status: resJob.statusCode });
            });
          });
          reqJob.on('error', err => resolve({ ok: false, error: err.message }));
