        } catch (e) {
          resolve({ ok: false, error: e.message });
        }
      });
    });
    reqToken.on('error', err => resolve({ ok: false, error: err.message }));
    reqToken.write(postData);
    reqToken.end();
  });
}

try {
  let targetCita = null;

  // 1. Caso A: erpCitaId es un código alfanumérico real tipo 'NEC-XXXX' o UUID
  if (erpCitaId && !/^\d{1,2}$/.test(erpCitaId)) {
    let p = '/rest/v1/clinica_citas?erp_cita_id=eq.' + encodeURIComponent(erpCitaId);
    if (erpCitaId.includes('-') && erpCitaId.length > 20) {
      p = '/rest/v1/clinica_citas?id=eq.' + encodeURIComponent(erpCitaId);
    }
    const cData = await getSupabase(p + '&select=*,clinica_pacientes(nombre,apellidos,dni)');
    if (Array.isArray(cData) && cData.length > 0) targetCita = cData[0];
  }

  // 2. Caso B: Resolución inteligente por DNI / Telegram / Índice de opción (1,2,3...) / Fecha y Hora
  if (!targetCita) {
    let dni = (input.dni || '').toString().toUpperCase().replace(/[^0-9A-Z]/gi, '').trim();
    let chat_id = null;
    try { chat_id = $('Normalizador de Mensaje').first().json.chat_id; } catch(e) {}

    let pacId = null;
    if (dni) {
      const pData = await getSupabase('/rest/v1/clinica_pacientes?dni=eq.' + encodeURIComponent(dni) + '&select=id,nombre,apellidos,dni');
      if (Array.isArray(pData) && pData.length > 0) pacId = pData[0].id;
    }
    if (!pacId && chat_id) {
      const pData = await getSupabase('/rest/v1/clinica_pacientes?telegram_chat_id=eq.' + chat_id + '&select=id,nombre,apellidos,dni');
      if (Array.isArray(pData) && pData.length > 0) pacId = pData[0].id;
    }

    if (pacId) {
      const activeCitas = await getSupabase('/rest/v1/clinica_citas?paciente_id=eq.' + pacId + '&estado=in.(PROGRAMADA,CONFIRMADA)&order=fecha_hora_inicio.asc&select=*,clinica_pacientes(nombre,apellidos,dni)');
      if (Array.isArray(activeCitas) && activeCitas.length > 0) {
        const fInput = (input.fecha || '').trim();
        const hInput = (input.hora || '').trim();
        if (fInput || hInput) {
          targetCita = activeCitas.find(c => {
            const f = (c.fecha_hora_inicio || '').slice(0, 10);
            const h = (c.fecha_hora_inicio || '').slice(11, 16);
            return (!fInput || f === fInput) && (!hInput || h === hInput);
          });
        }
        if (!targetCita && /^\d+$/.test(erpCitaId)) {
          const idx = parseInt(erpCitaId, 10) - 1;
          if (idx >= 0 && idx < activeCitas.length) {
            targetCita = activeCitas[idx];
          }
        }
      }
    }
  }

  if (!targetCita) {
    return JSON.stringify({
      estado: 'ERROR',
      mensaje: 'No se pudo identificar la cita a cancelar. Por favor especifica la fecha y hora de la cita.'
    });
  }

  const finalCitaId = targetCita.erp_cita_id || targetCita.id;
  const fechaCita = (targetCita.fecha_hora_inicio || '').slice(0, 10);
  const horaCita = (targetCita.fecha_hora_inicio || '').slice(11, 16);
  const pacNombre = targetCita.clinica_pacientes ? `${targetCita.clinica_pacientes.nombre || ''} ${targetCita.clinica_pacientes.apellidos || ''}`.trim() : '';
  const pacDni = targetCita.clinica_pacientes ? targetCita.clinica_pacientes.dni || '' : '';

  // 3. Actualizar estado en Supabase
  await patchSupabase('/rest/v1/clinica_citas?id=eq.' + targetCita.id, {
    estado: 'CANCELADA',
    fecha_actualizacion: new Date().toISOString()
  });

  // 4. Disparar UiPath con la acción CANCELAR y datos exactos
  const rpaRes = await dispararUiPath({
    in_ErpUrl: 'http://72.61.24.118:8080/',
    in_Accion: 'CANCELAR',
    in_ErpCitaId: finalCitaId,
    in_FechaCita: fechaCita,
    in_HoraCita: horaCita,
    in_NombrePaciente: pacNombre
  });

  if (!rpaRes.ok) {
    await notificarFalloRecepcion({
      proceso: 'Cancelación de Turno',
      accion: 'CANCELAR',
      paciente: pacNombre,
      dni: pacDni,
      fecha: fechaCita,
      hora: horaCita,
      error: 'El robot UiPath no pudo iniciar la cancelación en el ERP (' + (rpaRes.error || 'Código HTTP ' + rpaRes.status) + ')'
    });
  }

  return JSON.stringify({
    estado: 'EXITO',
    erp_cita_id: finalCitaId,
    fecha: fechaCita,
    hora: horaCita,
    paciente: pacNombre,
    uipath_disparado: rpaRes.ok,
    mensaje: `Tu cita del ${fechaCita} a las ${horaCita} hs ha sido cancelada correctamente.`
  });
} catch (err) {
  await notificarFalloRecepcion({
    proceso: 'Cancelación de Turno',
    accion: 'CANCELAR',
    paciente: '',
    dni: '',
    fecha: '',
    hora: '',
    error: err.message
  });
  return JSON.stringify({
    estado: 'ERROR',
    mensaje: err.message
  });
}

